def shapes(g):
    seen=set(); out=[]
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                for x,y in st:
                    cells.append((x,y))
                    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=nx<len(g) and 0<=ny<len(g[0]) and g[nx][ny]==v and (nx,ny) not in seen:
                            seen.add((nx,ny)); st.append((nx,ny))
                xs=[c[0] for c in cells]; ys=[c[1] for c in cells]
                norm=sorted((x-min(xs),y-min(ys)) for x,y in cells)
                out.append((v,norm,len(cells)))
    return out
